onClick:
{{
  (async function() {
    try {
      await Creer_OR_Depuis_Commande.run();
      await closeModal(modal_creer_or_commande.name);
      showAlert('✅ Intervention créée et liée à la commande !', 'success');

      // Réinitialisation ciblée (sans toucher au DatePicker pour éviter le crash)
      resetWidget('Sel_Type_OR_Cmd', true);
      resetWidget('Sel_Machine_OR_Cmd', true);
      resetWidget('Sel_Forfait_OR_Cmd', true);
      resetWidget('Sel_Mecano_OR_Cmd', true);
      resetWidget('Inp_Notes_OR_Cmd', true);

      await Get_Commande_ById.run();
      if (typeof Get_OR_Commande !== 'undefined') {
        await Get_OR_Commande.run();
      }
    } catch (err) {
      showAlert('❌ Erreur : ' + err.message, 'error');
    }
  })()
}}
